CREATE FUNCTION public.current_offer_revision(_revision bigint,_status text,_expires timestamptz) RETURNS bigint LANGUAGE sql STABLE SET search_path=public AS $$ SELECT _revision*2+CASE WHEN _status IN ('pending','countered','revised') AND _expires<=now() THEN 1 ELSE 0 END $$;
DO $change$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.offer_read_state(uuid[])'::regprocedure) INTO f;f:=replace(f,'''revision'',o.activity_revision','''revision'',public.current_offer_revision(o.activity_revision,o.status,o.expires_at)');f:=replace(f,'o.activity_revision>m.offer_revision','public.current_offer_revision(o.activity_revision,o.status,o.expires_at)>m.offer_revision');EXECUTE f;
SELECT pg_get_functiondef('public.mark_offers_read(jsonb)'::regprocedure) INTO f;f:=replace(f,'i.revision>o.activity_revision','i.revision>public.current_offer_revision(o.activity_revision,o.status,o.expires_at)');EXECUTE f;
SELECT pg_get_functiondef('public.network_offer_safe_detail(uuid)'::regprocedure) INTO f;f:=replace(f,'''activity_revision'',o.activity_revision','''activity_revision'',public.current_offer_revision(o.activity_revision,o.status,o.expires_at)');EXECUTE f;END $change$;
CREATE FUNCTION public.guard_pilot_safety_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.pilot_safety_evidence IS DISTINCT FROM OLD.pilot_safety_evidence AND current_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Independently verified migration evidence required';END IF;RETURN NEW;END $$;
CREATE TRIGGER guard_pilot_safety_evidence BEFORE UPDATE ON public.trip_network_settings FOR EACH ROW EXECUTE FUNCTION public.guard_pilot_safety_evidence();REVOKE ALL ON FUNCTION public.guard_pilot_safety_evidence(),public.current_offer_revision(bigint,text,timestamptz) FROM PUBLIC,anon,authenticated;